select ls.id, ls.leave_id as leaveId, ls.start_time as startTime, ls.end_time as endTime, ap.user_id as approvalPeopleId from leave_schedule ls left join employee_schedule es on ls.schedule_id=es.id left join approval_info ai on ai.leave_id=ls.leave_id left join approval_people ap on ap.id=ai.approval_people_id
es.inservice = 1
and es.employee_id = #{queryForm.userId}
and es.clinic_id = #{queryForm.orgId}
and DATE_FORMAT(es.work_date,'%Y-%m-%d') between DATE_FORMAT(#{queryForm.betweenDate},'%Y-%m-%d') and DATE_FORMAT(#{queryForm.andDate},'%Y-%m-%d')
